/* ---------- Proposal card ---------- */
/* a suggestion posted in the chat: no container; with .panel it becomes a card */
.prx{padding:14px 0;display:flex;flex-direction:column;gap:var(--dm-s-3)}
.prx.panel{padding:14px}
.prx-h{display:flex;gap:10px;align-items:center}
.prx-ic{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-pp-bg);color:var(--dm-pp);display:grid;place-items:center;flex:none}
.prx-ht{display:flex;flex-direction:column;min-width:0}
.prx-ht b{font-weight:500;font-size:13.5px}
.prx-ht span{font-size:12.5px}
.prx-diff{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px;border-radius:var(--dm-r-in);background:var(--dm-chip);flex-wrap:wrap}
.prx-sw{display:flex;align-items:center;gap:7px;font-size:12px;flex:1;min-width:0}
.prx-ar{color:var(--dm-muted);display:grid}
.prx-c{width:18px;height:18px;border-radius:calc(6px * var(--dm-rk));flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08);transition:background .5s var(--dm-ease)}
.prx-new .num{transition:opacity .3s}
.prx-cf{display:flex;align-items:center;gap:10px;font-size:12.5px}
.prx-seg{display:flex;gap:3px;flex:1}
.prx-seg i{flex:1;height:5px;border-radius:3px;background:var(--dm-line);transition:background .4s}
.prx-seg i.on{background:var(--dm-ok)}
.prx-pc{width:34px;text-align:right;color:var(--dm-fg2)}
.prx-alt-t{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--dm-fg2);align-self:flex-start}
.prx-alt-t svg{transition:transform .4s var(--dm-ease)}
.prx-alt-t.open svg{transform:rotate(90deg)}
.prx-alts{display:flex;flex-direction:column;gap:2px;padding-top:2px;margin-inline:-8px}
.prx-a{display:flex;align-items:center;gap:9px;padding:7px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));font-size:13px;text-align:left;transition:background .25s}
@media (hover:hover) and (pointer:fine){.prx-a:hover{background:var(--dm-row)}}
.prx-a .d{margin-left:auto;font-size:12px;color:var(--dm-muted)}
.prx-f{display:flex;justify-content:flex-end;gap:6px}
.prx-done{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px;color:var(--dm-ok);flex:1}

DM.def('proposal-card', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{wand}', I('wand')).replace('{right}', I('right','xs')).replace('{chev}', I('chev-r','xs'));
  const segs = $$('.prx-seg i', r), pc = $('.prx-pc', r), at = $('.prx-alt-t', r), alt = $('.prx-alt', r), f = $('.prx-f', r);
  const nw = $('.prx-new', r);
  const all = [
    { bg:'#5b6472', hex:'#5B6472', ratio:'5.9 : 1', conf:84, name:'Suggested', d:'Balanced with the primary' },
    { bg:'#475161', hex:'#475161', ratio:'7.4 : 1', conf:62, name:'Darker', d:'Stronger than the primary' },
    { bg:'#116ff8', hex:'#116FF8', ratio:'4.6 : 1', conf:41, name:'Accent outline', d:'Competes with the CTA' }
  ];
  let cur = 0;
  const alts = $('.prx-alts', r);
  function conf(v){ tween(+pc.textContent.replace('%','') || 0, v, 700, x => { pc.textContent = Math.round(x) + '%'; segs.forEach((s, i) => s.classList.toggle('on', x >= (i + 1) * 20 - 10)); }); }
  function list(){ alts.innerHTML = all.map((o, i) => i === cur ? '' : `<button class="prx-a" data-i="${i}"><span class="prx-c" style="background:${o.bg}"></span><span>${o.name}, ${o.ratio}</span><span class="d">${o.d}</span></button>`).join(''); $$('.prx-a', alts).forEach(a => a.onclick = () => apply(+a.dataset.i)); }
  function apply(i){ cur = i; const o = all[i]; $('.prx-c', nw).style.background = o.bg; swap($('.num', nw), o.hex); swap($('.prx-rt', nw), o.ratio); conf(o.conf); list(); stagger($$('.prx-a', alts), 50); }
  at.onclick = () => { const op = alt.classList.toggle('shut'); at.classList.toggle('open', !op); };
  list();
  let saved;
  const reset = () => { f.innerHTML = saved; bind(); };
  function bind(){
    $('.prx-ok', r).onclick = () => { saved = f.innerHTML; alt.classList.add('shut'); at.classList.remove('open');
      f.innerHTML = `<span class="prx-done">${I('ok')}<span>Applied to 3 buttons</span></span><button class="pill ghost sm prx-un">${I('undo','xs')}Undo</button>`; stagger([...f.children], 60);
      $('.prx-un', r).onclick = reset; };
    $('.prx-no', r).onclick = () => { saved = f.innerHTML; f.innerHTML = `<span class="prx-done muted" style="color:var(--dm-muted)">Dismissed. The agent will not suggest this again.</span><button class="pill ghost sm prx-un">Undo</button>`; stagger([...f.children], 60); $('.prx-un', r).onclick = reset; };
  }
  bind(); c.later(400, () => conf(84));
});
